class Solution {
  public int minOperations(String s, int k) {
    int n = s.length(), zeros = 0;
    for (int i = 0; i < n; i++) if (s.charAt(i) == '0') zeros++;
    if (zeros == 0) return 0;
    int ones = n - zeros;
    for (long t = 1; t <= 2L * n + 5; t++) {
      long total = t * k;
      if (total < zeros || (total - zeros) % 2 != 0) continue;
      long zeroCap = zeros * (t % 2 == 1 ? t : t - 1);
      long oneCap = ones * (t % 2 == 0 ? t : t - 1);
      if (zeroCap + oneCap >= total) return (int) t;
    }
    return -1;
  }
}
